@Test
public void testNewIdentityHashSet_1_oe() {
    final Set<String> set = SetUtils.newIdentityHashSet();
    final String a = new String("a");
    set.add(a);
    set.add(new String("b"));
    set.add(a);

    assertEquals(2, set.size());
}

@Test
public void testNewIdentityHashSet_2_oe() {
    final Set<String> set = SetUtils.newIdentityHashSet();
    final String a = new String("a");
