    son.put(5, "C");
    son.put(6, grandfather);
    son.put(7, father);

    outPrint.println(LABEL + " = ");
    outPrint.println("{");
    outPrint.println(INDENT + "0 = A " + String.class.getName());
    outPrint.println(INDENT + "1 = ");
    outPrint.println(INDENT + "{");
    outPrint.println(INDENT + INDENT + "2 = B " + String.class.getName());
