    outPrint.println("} " + TreeMap.class.getName());

    final String EXPECTED_OUT = out.toString();

    out.reset();
    MapUtils.debugPrint(outPrint, "Print Map", grandfather);

    assertEquals(EXPECTED_OUT, out.toString());
}

