    final DefaultKeyValue<K, V> kv2 = new DefaultKeyValue<>(kv);
    // removed other assertion

    // test that the KVPs are independent
    kv.setKey(null);
    kv.setValue(null);

    // removed other assertion

    // 4. test Map.Entry constructor
    final Map<K, V> map = new HashMap<>();
