public void testUniqueListReInsert_2_oe() {
    final List<E> l = SetUniqueList.setUniqueList(new LinkedList<E>());
    l.add((E) new Object());
    l.add((E) new Object());

    final E a = l.get(0);

    // duplicate is removed
